/* Specific ability tags agreed with the Campaign engine (PR #44). Each family's broad tag is kept in
   the index for compatibility, and every broad tag a character holds comes with at least one specific
   tag from its own family. Elemental families are separate, so an ice feat can never prove fire. */
const CHARACTER_ABILITY_TAG_FAMILIES = Object.freeze({
  flight: Object.freeze(['natural-flight', 'powered-flight', 'glide', 'pilot', 'mount']),
  magic: Object.freeze(['spellcaster', 'magic-item']),
  psychic: Object.freeze(['telepathy', 'telekinesis', 'mind-control']),
  aquatic: Object.freeze(['water-breathing', 'swimmer', 'water-control']),
  fire: Object.freeze(['fire-control', 'fire-weapon']),
  ice: Object.freeze(['ice-control', 'ice-weapon']),
  electric: Object.freeze(['electric-control', 'electric-weapon']),
  tech: Object.freeze(['powered-armor', 'robot-or-ai', 'cyborg', 'gadgets', 'inventor']),
  stealth: Object.freeze(['invisibility', 'infiltration']),
  teleport: Object.freeze(['self-teleport', 'portals', 'teleports-others']),
  healing: Object.freeze(['self-regeneration', 'heals-others']),
  giants: Object.freeze(['giant-sized', 'size-change']),
});
const CHARACTER_ABILITY_BROAD_TAG = Object.freeze(Object.fromEntries(Object.entries(CHARACTER_ABILITY_TAG_FAMILIES)
  .flatMap(([broad, list]) => [[broad, broad], ...list.map(t => [t, broad])])));
/* BEGIN GENERATED ABILITY INDEX (node tools/ability-audit.cjs --write-index).
   Every roster character is listed, so [] means "audited: no qualifying power", not "unknown".
   Each broad Campaign power id is followed by its specific tags (CHARACTER_ABILITY_TAG_FAMILIES).
   Derived only from CHARACTER_ABILITIES evidence and CHARACTER_ABILITY_CARRYOVER, minus incorrect
   disputes; characterAbilityProvenance() tells the two apart. Challenge criteria read this index. */
